 if(j.status==='Completed')row.append(button('Review saved section preview',async()=>{const r=await api({action:'job',projectId:view.project.id,jobId:j.id});showDraftPreview(r.job);},true));
 else if(['Pending','Processing','Failed'].includes(j.status)&&canWrite())row.append(button('Resume section job',async()=>{if(j.status==='Failed')await mutate('retryJob',{jobId:j.id});await waitJob(j.id);},true));
