async function waitJob(id){for(let i=0;i<45;i++){const r=await api({action:'job',projectId:view.project.id,jobId:id});const j=r.job;if(j.status==='Completed'){if(j.kind==='draft'){showDraftPreview(j);}else{await open(view.project.id);message('Submission package saved. Download it in Exports.');}return;}if(['Failed','Cancelled'].includes(j.status))throw Error('Job '+j.status+(j.error_code?': '+jobErrorLabel(j.error_code):'')+'. Saved content is unchanged. Retry is available below.');message('Background '+j.kind+' job: '+j.status+' · attempt '+j.attempts);await new Promise(r=>setTimeout(r,2000));}message('Job continues in the background. Use Reload saved version to check its status.');}
function reviews(parent,s){const team=card(parent,'Explicit project access');for(const m of view.members){team.append(node('p',(m.label||m.user_id)+' · project '+m.role+' · organization '+m.orgRole));if(view.role==='manager'&&m.user_id!==view.project.created_by)team.append(button('Remove project access',async()=>{await api({action:'member',projectId:view.project.id,userId:m.user_id,role:m.role,remove:true});await open(view.project.id);message('Project access removed.');},true));}if(view.role==='manager'){const f=form(team,'Add / change an existing organization member',async()=>{await api({action:'member',projectId:view.project.id,userId:id.value,role:role.value,remove:false});await open(view.project.id);message('Project access saved.');});const id=view.directory?.length?select(f,'Organization member',view.directory.map(m=>[m.user_id,m.label]),''):field(f,'Existing organization member user ID'),role=select(f,'Project role',['author','reviewer','viewer','manager'],'author');submit(f,'Save project access');team.append(node('p','Invite organization members through Knowledge base → Team first. A display name never grants access.'));}
 const comments=card(parent,'Comments and mentions');for(const x of s.comments)comments.append(node('p',`${x.actor} · ${x.createdAt}${x.sectionId?' · section '+x.sectionId:''}`),node('blockquote',x.text));if(canWrite()){const f=form(comments,'Add a comment',async()=>{await mutate('comment',{text:text.value,sectionId:section.value||null,mentions:[...mentions.selectedOptions].map(x=>x.value)});render();});const text=field(f,'Comment (internal only)','textarea'),section=select(f,'Section',[['','Project'],...s.sections.map(x=>[x.id,x.title])],''),mentions=select(f,'Mention current members',view.members.map(m=>[m.user_id,m.label||m.user_id]),'');mentions.multiple=true;text.required=true;submit(f,'Post comment');}
 const historyCard=card(parent,'Revision comparisons and approval history');let historyPage=0;const historyButton=button('Load revision history',async()=>{const r=await api({action:'history',projectId:view.project.id,page:historyPage});historyPage++;historyButton.textContent=r.revisions.length===25?'Load older revisions':'All available revisions loaded';historyButton.disabled=r.revisions.length<25;for(const x of r.revisions){historyCard.append(button(`Compare revision ${x.revision} · ${x.operation}`,async()=>{const old=await api({action:'revision',projectId:view.project.id,revision:x.revision});const out=card(historyCard,'Then / current');for(const sec of s.sections){const prev=old.revision.state.sections.find(y=>y.id===sec.id);if(prev?.text!==sec.text)out.append(node('h4',sec.title),node('pre','THEN:\n'+(prev?.text||'(not present)')+'\n\nCURRENT:\n'+sec.text));}if(!out.querySelector('pre'))out.append(node('p','No section text changes. Metadata or reviews may differ.'));},true));}});historyCard.append(historyButton);for(const a of view.approvals)historyCard.append(node('p',`Immutable approval snapshot · revision ${a.revision} · ${a.section_id||'final project'} · ${a.actor_id}`));const feed=card(parent,'Project activity');for(const e of view.events)feed.append(node('p',`${e.created_at} · ${e.action} · revision ${e.revision} · ${e.actor_id}`));
 for(const section of s.sections){const c=node('details');c.append(node('summary',section.title+' · '+section.status));parent.append(c);c.append(node('p',section.status+' · section revision '+section.revision),node('blockquote',section.text),node('p',section.reviewReason||''));if(canReview()){const f=form(c,'Review saved text',async()=>{await mutate('reviewSection',{sectionId:section.id,sectionRevision:section.revision,status:status.value,reason:reason.value,confirmEvidence:checked.checked});render();});const status=select(f,'Decision',['changes requested','approved'],section.status),reason=field(f,'Review explanation','textarea');reason.required=true;const l=node('label'),checked=node('input');checked.type='checkbox';l.append(checked,node('span',' I verified factual claims against eligible sources and checked submission instructions.'));f.append(l);submit(f,'Record revision review');}}}

async function download(id){const r=await api({action:'download',projectId:view.project.id,fileId:id});const a=node('a');a.href=r.url;a.download=r.name;a.rel='noopener';a.click();}
function exportsPanel(parent,s){parent.append(node('p','DOCX, PDF and compliance XLSX/CSV use the same saved revision. The ZIP also includes a readiness report (readiness-report.md) with unresolved items first and unresolved mandatory items in the first section. The manifest lists included files, hashes and unresolved items. Internal comments are excluded. Generated packages expire after seven days.'));
 if(canWrite()){parent.append(button('Render and download a draft package',async()=>{const r=await mutate('export',{draft:true,requestKey:crypto.randomUUID()});await waitJob(r.job.id);}));const f=form(parent,'Authorized final sign-off',async()=>{await mutate('finalApprove',{reason:reason.value});render();});const reason=field(f,'Final review explanation','textarea');reason.required=true;submit(f,'Sign off this saved content');f.hidden=!canReview();if(canReview())parent.append(button('Generate final submission package',async()=>{const r=await mutate('export',{draft:false,requestKey:crypto.randomUUID()});await waitJob(r.job.id);}));else parent.append(node('p','Final submission needs a reviewer sign-off. Ask a manager or reviewer to sign off first.'));
 const attach=form(parent,'Include an authorized supporting attachment',async()=>{await mutate('attachment',{documentId:doc.value,requirementIds:[...req.selectedOptions].map(x=>x.value)});render();});const doc=field(attach,'Ready knowledge-base document ID (copy it from your Knowledge Library)'),req=select(attach,'Satisfies requirements',s.requirements.map(r=>[r.id,r.text]),'');req.multiple=true;submit(attach,'Copy private attachment into project');}
 checklist(parent);
 for(const a of s.attachments){const c=card(parent,a.name);c.append(node('p',a.requirementIds.join(', ')),button('Download attachment',()=>download(a.fileId),true));if(canWrite())c.append(button('Remove from package',async()=>{await mutate('removeAttachment',{fileId:a.fileId});render();},true));}
 for(const j of view.jobs){const sec=j.result?.sectionId?s.sections.find(x=>x.id===j.result.sectionId):null;const c=card(parent,(sec?sec.title+' · ':'')+j.kind+' · revision '+j.revision+' · '+j.status);c.append(node('p','Attempts '+j.attempts+' / 3'));const failure=jobErrorText(j);if(failure)c.append(node('p',failure));if(j.status==='Completed'&&j.result?.fileId){const file=view.files.find(f=>f.id===j.result.fileId);const expired=!file||(file.expires_at&&Date.parse(file.expires_at)<=Date.now());if(expired)c.append(node('p','This package has expired or is no longer available. Generate a new package from the current saved proposal.'));else{c.append(node('p','Available until '+(file.expires_at?new Date(file.expires_at).toLocaleString():'the current access expires')),button('Download package'+(j.result.draft?' (DRAFT)':''),()=>download(j.result.fileId)));}}if(j.status==='Completed'&&j.kind==='draft')c.append(button('Review saved section preview',async()=>{const r=await api({action:'job',projectId:view.project.id,jobId:j.id});showDraftPreview(r.job);},true));if(['Pending','Processing','Failed'].includes(j.status)&&canWrite())c.append(button('Retry / resume job',async()=>{await mutate('retryJob',{jobId:j.id});await waitJob(j.id);},true));}
}
$('reload').onclick=()=>{if(dirty&&!confirm('Your unsaved text will be discarded. Copy it first if needed. Reload anyway?'))return;clearTimeout(saveTimer);dirty=false;run(()=>open(view.project.id));};
$('back').onclick=()=>{if(dirty&&!confirm('Your unsaved text will be discarded. Copy it first if needed. Go back to projects anyway?'))return;clearTimeout(saveTimer);dirty=false;showProjects();};
$('close-preview').onclick=()=>$('preview').close();$('accept').onclick=()=>run(async()=>{await mutate('acceptDraft',{sectionId:previewJob.result.sectionId,jobId:previewJob.id,confirmReplace:true});$('preview').close();render();message('Suggested section accepted and saved. Review is still required.');});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
async function init(){const response=await fetch('/.netlify/functions/proposal-config'),config=await response.json();if(!response.ok||!config.enabled)throw Error(config.error||'Proposal workspace is not enabled for this deployment.');featureFlags=config.features||{};client=createClient(config.url,config.key);const sessionResult=await client.auth.getSession();user=sessionResult.data.session?.user;if(!user){const id=location.hash.slice(1);$('login').querySelector('a').href='/auth.html?next=workspace'+(/^[a-f0-9-]{36}$/i.test(id)?'&project='+encodeURIComponent(id):'');$('login').hidden=false;message('Sign in to access your private projects.');return;}client.auth.onAuthStateChange((event,s)=>{if(user&&s?.user?.id!==user.id){void identifyUsage(null);accountEpoch++;user=null;view=null;dirty=false;clearTimeout(saveTimer);$('app').hidden=true;$('login').hidden=false;$('panel').replaceChildren();message('Account changed. Sign in and reload.');}});await session();$('app').hidden=false;const orgs=await knowledge({action:'organizations'});const creatable=orgs.organizations.filter(o=>['owner','editor'].includes(o.role));$('create').hidden=!creatable.length;for(const o of creatable)$('organization').append(new Option(o.kb_organizations.name,o.org_id));if(!orgs.organizations.length)message('Create an organization in Knowledge base first.');$('create').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target),r=await api({action:'create',orgId:$('organization').value,title:f.get('title'),company:f.get('company')});await projects();await open(r.id);});};if($('project-search'))$('project-search').onsubmit=e=>{e.preventDefault();projectQuery=$('project-query').value;run(()=>projects());};await projects();const prefill=new URLSearchParams(location.search).get('analysis');if(prefill&&/^[a-f0-9-]{36}$/i.test(prefill))prefillAnalysisId=prefill;const id=location.hash.slice(1);if(/^[a-f0-9-]{36}$/i.test(id))await open(id);else message(creatable.length?'Choose a project or create one.':orgs.organizations.length?'Open a shared project below, or ask your organization owner for project access.':'Create an organization in Knowledge base, then return to start a proposal project.');}
init().catch(e=>message(e.message,true));
